def count_opposite_parity_to_right(nums):
    remaining=[sum(x%2==0 for x in nums),sum(x%2!=0 for x in nums)];out=[]
    for x in nums:
        remaining[x&1]-=1;out.append(remaining[(x&1)^1])
    return out

